144: extern "C" void initMonteCarloGPU(TOptionPlan *plan) {
145:   checkCudaErrors(cudaMalloc(&plan->d_OptionData,
146:                              sizeof(__TOptionData) * (plan->optionCount)));
147:   checkCudaErrors(cudaMalloc(&plan->d_CallValue,
