151:   // Allocate internal device memory
152:   checkCudaErrors(cudaMallocHost(&plan->h_CallValue,
153:                                  sizeof(__TOptionValue) * (plan->optionCount)));
154:   // Allocate states for pseudo random number generators
155:   checkCudaErrors(cudaMalloc((void **)&plan->rngStates,
156:                              plan->gridSize * THREAD_N * sizeof(curandState)));
157:   checkCudaErrors(cudaMemset(plan->rngStates, 0,
158:                              plan->gridSize * THREAD_N * sizeof(curandState)));
