165: // Compute statistics and deallocate internal device memory
166: extern "C" void closeMonteCarloGPU(TOptionPlan *plan) {
167:   for (int i = 0; i < plan->optionCount; i++) {
168:     const double RT = plan->optionData[i].R * plan->optionData[i].T;
169:     const double sum = plan->h_CallValue[i].Expected;
170:     const double sum2 = plan->h_CallValue[i].Confidence;
171:     const double pathN = plan->pathN;
172:     // Derive average from the total sum and discount by riskfree rate
173:     plan->callValue[i].Expected = (float)(exp(-RT) * sum / pathN);
174:     // Standard deviation
175:     double stdDev = sqrt((pathN * sum2 - sum * sum) / (pathN * (pathN - 1)));
176:     // Confidence width; in 95% of all cases theoretical value lies within these
177:     // borders
178:     plan->callValue[i].Confidence =
179:         (float)(exp(-RT) * 1.96 * stdDev / sqrt(pathN));
180:   }
185:   checkCudaErrors(cudaFree(plan->d_CallValue));
186:   checkCudaErrors(cudaFree(plan->d_OptionData));
187: }
